starterTemplate:
#include <iostream>
#include <vector>

/* 两间屋子的登记表：名字先报上，正文还没有人写 */
int countBig(const std::vector<int>& ws);

int sumAll(const std::vector<int>& ws);

/* ① 把 countBig 的正文补完：满 50 克才算大条，数一数有几条 */
/* ② 把 sumAll 的正文补完：一条条加起来 */

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<int> ws(n);
    for (int i = 0; i < n; i++) {
        std::cin >> ws[i];
    }
    std::cout << "大条 " << countBig(ws) << " 尾，合计 " << sumAll(ws) << " 克" << std::endl;
    return 0;
}

referenceSolutionTemplate:
#include <iostream>
#include <vector>

/* 两间屋子的登记表：名字先报上，正文还没有人写 */
int countBig(const std::vector<int>& ws);

int sumAll(const std::vector<int>& ws);

int countBig(const std::vector<int>& ws) {
    int c = 0;
    for (int i = 0; i < static_cast<int>(ws.size()); i++) {
        if (ws[i] >= 50) {
            c++;
        }
    }
    return c;
}

int sumAll(const std::vector<int>& ws) {
    int s = 0;
    for (int i = 0; i < static_cast<int>(ws.size()); i++) {
        s += ws[i];
    }
    return s;
}

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<int> ws(n);
    for (int i = 0; i < n; i++) {
        std::cin >> ws[i];
    }
    std::cout << "大条 " << countBig(ws) << " 尾，合计 " << sumAll(ws) << " 克" << std::endl;
    return 0;
}

explanationTemplate:
两条正文都是一圈走一遍的活儿（本课练过几十遍的套路），这题真正想让你体会的是**报名和正文成对**：登记表上那两行报名已经写好了，正文补上去之后，**两边名字逐字对上**，对号才接得住。

```cpp
int countBig(const std::vector<int>& ws) {
    int c = 0;
    for (int i = 0; i < static_cast<int>(ws.size()); i++) {
        if (ws[i] >= 50) {
            c++;
        }
    }
    return c;
}
```

数大条这一条，比算总重多一道小小的「这算不算」：**满 50 克** 才 `c++` 一下。另一条就是老朋友，一圈加起来。两条的形态要和登记表上报名的那行**逐字一致** —— 登记表怎么报的，正文就怎么写（`const` 和 `&` 一个字都别少）。

⚠️ 顺便认清一张典型的脸：**只报名、忘了写正文**（或者正文写成了别的名字），对号时都是 `undefined reference` —— 名到、人没到，流水线就停在那儿。改的时候记得：**名字是唯一的接头暗号喵。**
